namespace Tests;
public class AdminListsTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Admin_customers_audit_and_tickets_filter_permissions_and_pagination()
    {
        var admin=await Admin();var customer=await LoginPhone("9890000061","Synthetic Buyer");var seller=await LoginPhone("9890000062","Synthetic Seller");var r=await seller.Post("/api/seller/register",new{display_name="Synthetic List Store"});var sid=r.Json["id"]!.GetValue<string>();
        Assert.Equal(403,(await customer.Get("/api/admin/customers")).Status);Assert.Equal(403,(await customer.Get("/api/admin/audit")).Status);Assert.Equal(403,(await customer.Get("/api/admin/tickets")).Status);
        r=await admin.Get("/api/admin/customers?kind=sellers&q=%20Synthetic%20");Assert.True(r.Status==200,r.ToString());Assert.Single(r.Json["items"]!.AsArray());Assert.Equal(sid,r.Json["items"]![0]!["seller"]!["id"]!.GetValue<string>());Assert.Equal(0,r.Json["items"]![0]!["orders"]!.GetValue<int>());
        r=await admin.Get("/api/admin/customers?kind=customers&q=9890000061");Assert.Single(r.Json["items"]!.AsArray());var uid=r.Json["items"]![0]!["id"]!.GetValue<string>();Assert.Null(r.Json["items"]![0]!["seller"]);Assert.Single((await admin.Get("/api/admin/customers?kind=staff")).Json["items"]!.AsArray());
        await ApiFactory.DbExecAsync("UPDATE users SET is_active=0 WHERE id=@uid",new{uid});Assert.Single((await admin.Get("/api/admin/customers?kind=blocked")).Json["items"]!.AsArray());r=await admin.Get("/api/admin/customers?page_size=1&page=2");Assert.Equal(3,r.Json["total"]!.GetValue<int>());Assert.Single(r.Json["items"]!.AsArray());await ApiFactory.DbExecAsync("UPDATE users SET deleted_at=UTC_TIMESTAMP(6),is_active=1 WHERE id=@uid",new{uid});Assert.Empty((await admin.Get("/api/admin/customers?q=9890000061")).Json["items"]!.AsArray());await ApiFactory.DbExecAsync("UPDATE users SET deleted_at=NULL WHERE id=@uid",new{uid});
        Assert.Equal(422,(await admin.Get("/api/admin/customers?kind=unknown")).Status);Assert.Equal(422,(await admin.Get("/api/admin/customers?page_size=101")).Status);Assert.Equal(422,(await admin.Get("/api/admin/audit?page=0")).Status);
        await ApiFactory.DbExecAsync("INSERT INTO audit_logs(id,action,entity_type,entity_id,detail,created_at)VALUES(UUID(),'synthetic.read','synthetic','synthetic-list','Synthetic only',UTC_TIMESTAMP(6))");r=await admin.Get("/api/admin/audit?entity_id=synthetic-list");Assert.Single(r.Json["items"]!.AsArray());Assert.Equal("system",r.Json["items"]![0]!["actor"]!.GetValue<string>());Assert.Empty((await admin.Get("/api/admin/audit?entity_id=synthetic-list&page=2")).Json["items"]!.AsArray());
        r=await customer.Post("/api/support/tickets",new{category="account",subject="Synthetic list ticket",message="Synthetic support message",is_grievance=true});Assert.True(r.Status==201,r.ToString());var tid=r.Json["id"]!.GetValue<string>();await ApiFactory.DbExecAsync("UPDATE support_tickets SET ack_due_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 HOUR) WHERE id=@tid",new{tid});
        r=await admin.Get("/api/admin/tickets?overdue=true&grievance=true&q=%20Synthetic%20");Assert.True(r.Status==200,r.ToString());Assert.Single(r.Json["items"]!.AsArray());Assert.Equal("Synthetic Buyer",r.Json["items"]![0]!["customer"]!.GetValue<string>());Assert.True(r.Json["items"]![0]!["ack_overdue"]!.GetValue<bool>());Assert.Null(r.Json["items"]![0]!["messages"]);Assert.Equal(1,r.Json["status_counts"]!["open"]!.GetValue<int>());
        await ApiFactory.DbExecAsync("UPDATE support_tickets SET status='resolved',acknowledged_at=UTC_TIMESTAMP(6) WHERE id=@tid",new{tid});Assert.Empty((await admin.Get("/api/admin/tickets")).Json["items"]!.AsArray());Assert.Single((await admin.Get("/api/admin/tickets?status=")).Json["items"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/tickets?status=&overdue=true")).Json["items"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/tickets?status=resolved&page=2")).Json["items"]!.AsArray());
    }
}
